import requests
queries=['("platelet-specific"[Title/Abstract] AND "factor VIII"[Title/Abstract] AND mouse AND hemophilia)','("2bF8" AND thrombosis)','(platelet-derived factor VIII AND hemophilia A AND mouse)']
for q in queries:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':30,'sort':'relevance'},timeout=20)
 ids=r.json()['esearchresult']['idlist']; print('\nQUERY',q,'\n',ids)
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()
  for i in ids:
   d=s['result'][i]; print(i,d.get('pubdate'),d.get('title'))
